from django.db import migrations, models


def theme_from_colors(apps, schema_editor):
    """A store that had picked a dark background gets the night theme."""
    StoreSettings = apps.get_model("core", "StoreSettings")
    for store in StoreSettings.objects.all():
        hex_ = (store.color_background or "#E5D7C1").lstrip("#")
        try:
            r, g, b = (int(hex_[i:i + 2], 16) for i in (0, 2, 4))
        except ValueError:
            continue
        if 0.2126 * r + 0.7152 * g + 0.0722 * b < 128:
            store.theme = "night"
            store.save(update_fields=["theme"])


